void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;

    // Lazy global rescaling when the increment factor becomes too large
    if (var_inc > 1e90) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // Update activity of the variable
    activity[var] += var_inc * coeff;

    // Local rescaling if this variable's activity overflows
    if (activity[var] > 1e100) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // Keep the VSIDS heap consistent
    if (vsids.inHeap(var)) vsids.update(var);
}
